"use server";

import { createClient } from "@supabase/supabase-js";
import { revalidatePath } from "next/cache";
import { redirect } from "next/navigation";

// Initialize Supabase Client for Server Actions
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL;
const supabaseKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY;

export async function createPortfolioItem(formData: FormData) {
    if (!supabaseUrl || !supabaseKey) {
        return { error: "Supabase authentication missing. Check .env.local" };
    }

    const supabase = createClient(supabaseUrl, supabaseKey);

    const title = formData.get("title") as string;
    const category = formData.get("category") as string;
    const tier = formData.get("tier") as string;
    const description = formData.get("description") as string;
    const techStackRaw = formData.get("tech_stack") as string;
    const liveUrl = formData.get("live_url") as string;
    const status = formData.get("status") as string;
    const isFeatured = formData.get("is_featured") === "on";

    // Basic validation
    if (!title || !category) {
        return { error: "Title and Category are required." };
    }

    // Generate Slug
    const slug = title
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/(^-|-$)+/g, "");

    const techStack = techStackRaw.split(",").map((t) => t.trim());

    // Insert into DB
    const { error } = await supabase.from("portfolio_items").insert({
        title,
        slug,
        category,
        tier,
        description,
        tech_stack: techStack,
        live_url: liveUrl,
        status,
        is_featured: isFeatured,
        // For now, we'll just placeholder images until real upload is set up
        thumbnail_url: "/api/placeholder/400/320",
        images: [],
    });

    if (error) {
        console.error("Supabase Error:", error);
        return { error: error.message };
    }

    revalidatePath("/admin/portfolio");
    redirect("/admin/portfolio");
}
